.category-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.5rem;
    margin-top: 1rem;
}

.category-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 1.5rem;
    transition: box-shadow 0.2s;
}

.category-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
}

.category-card h3 {
    margin-top: 0;
}

.category-card a {
    font-weight: 600;
    color: #0366d6;
}

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Bruschetta", Category = "appetizers", Ingredients = "Baguette
Tomatoes
Basil
Garlic
Olive oil", Steps = "1. Slice and toast baguette
2. Dice tomatoes with garlic and basil
3. Drizzle with olive oil
4. Spoon mixture onto bread", AverageRating = 4.2, RatingCount = 15 },
        new Recipe { Id = 2, Title = "Stuffed Mushrooms", Category = "appetizers", Ingredients = "Button mushrooms
Cream cheese
Garlic
Parsley
Breadcrumbs", Steps = "1. Remove mushroom stems
2. Mix cream cheese, garlic, parsley
3. Fill caps with mixture
4. Top with breadcrumbs
5. Bake at 375°F for 20 min", AverageRating = 4.5, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Spaghetti Carbonara", Category = "main-courses", Ingredients = "Spaghetti
Pancetta
Eggs
Parmesan
Black pepper", Steps = "1. Cook spaghetti al dente
2. Fry pancetta until crisp
3. Whisk eggs with parmesan
4. Toss hot pasta with pancetta
5. Stir in egg mixture off heat", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 4, Title = "Grilled Salmon", Category = "main-courses", Ingredients = "Salmon fillets
Lemon
Dill
Olive oil
Salt and pepper", Steps = "1. Season salmon with salt, pepper, dill
2. Drizzle with olive oil
3. Grill skin-side down 4-5 min
4. Flip and cook 3 min more
5. Squeeze lemon over top", AverageRating = 4.6, RatingCount = 12 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "desserts", Ingredients = "Dark chocolate
Butter
Eggs
Sugar
Flour", Steps = "1. Melt chocolate and butter
2. Whisk eggs and sugar
3. Fold in flour and chocolate mixture
4. Pour into ramekins
5. Bake at 425°F for 12 min", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 6, Title = "Tiramisu", Category = "desserts", Ingredients = "Ladyfingers
Mascarpone
Espresso
Cocoa powder
Eggs
Sugar", Steps = "1. Whisk egg yolks with sugar
2. Fold in mascarpone
3. Dip ladyfingers in espresso
4. Layer cookies and cream
5. Dust with cocoa
6. Refrigerate 4 hours", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Mango Smoothie", Category = "beverages", Ingredients = "Mango
Yogurt
Honey
Ice
Milk", Steps = "1. Peel and chop mango
2. Add all ingredients to blender
3. Blend until smooth
4. Serve immediately", AverageRating = 4.3, RatingCount = 10 },
        new Recipe { Id = 8, Title = "Iced Matcha Latte", Category = "beverages", Ingredients = "Matcha powder
Hot water
Milk
Ice
Honey (optional)", Steps = "1. Sift matcha into a cup
2. Add hot water and whisk
3. Fill glass with ice
4. Pour milk over ice
5. Add matcha and stir", AverageRating = 4.1, RatingCount = 7 },
    };

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category == category).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }
}

@page "/recipes/{Category}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@GetCategoryTitle() - RecipeShare</PageTitle>

<h1>@GetCategoryTitle()</h1>

<nav><a href="/">← Back to Categories</a></nav>

@if (recipes.Any())
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <div class="recipe-card">
                <h3><a href="/recipe/@recipe.Id">@recipe.Title</a></h3>
                <p>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Category);
    }

    private string GetCategoryTitle() => Category switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        "beverages" => "🥤 Beverages",
        _ => Category
    };
}

.recipe-list {
    display: grid;
    gap: 1rem;
    margin-top: 1rem;
}

.recipe-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 1rem 1.5rem;
}

.recipe-card h3 {
    margin: 0 0 0.5rem;
}

.recipe-card a {
    color: #0366d6;
    text-decoration: none;
}

.recipe-card a:hover {
    text-decoration: underline;
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

@if (recipe is not null)
{
    <PageTitle>@recipe.Title - RecipeShare</PageTitle>

    <nav><a href="/recipes/@recipe.Category">← Back to Category</a></nav>

    <h1>@recipe.Title</h1>
    <p>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>

    <h2>Ingredients</h2>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@step.TrimStart("0123456789. ".ToCharArray())</li>
        }
    </ol>

    <h2>Rate this Recipe</h2>
    <StarRating RecipeId="recipe.Id" />
}
else
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/">← Back to Home</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= selectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              title="@star star(s)">
            @(star <= selectedRating ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="rating-feedback">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    font-size: 1.5rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star:hover,
.star.selected {
    color: #f5a623;
}

.rating-feedback {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #28a745;
}

@page "/submit"
@using RecipeShare.Services
@using RecipeShare.Models
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (successMessage is not null)
{
    <div class="alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="form-group">
        <label for="title">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" />
        <ValidationMessage For="() => model.Title" />
    </div>

    <div class="form-group">
        <label for="category">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-control">
            <option value="">-- Select a Category --</option>
            <option value="appetizers">Appetizers</option>
            <option value="main-courses">Main Courses</option>
            <option value="desserts">Desserts</option>
            <option value="beverages">Beverages</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" />
    </div>

    <div class="form-group">
        <label for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5" />
        <ValidationMessage For="() => model.Ingredients" />
    </div>

    <div class="form-group">
        <label for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="5" />
        <ValidationMessage For="() => model.Steps" />
    </div>

    <button type="submit" class="btn-submit">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };

        RecipeService.AddRecipe(recipe);
        successMessage = $"'{model.Title}' was submitted successfully!";
        model = new();
    }
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.form-control {
    width: 100%;
    max-width: 500px;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.btn-submit {
    background: #0366d6;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-submit:hover {
    background: #0256b9;
}

.alert-success {
    background: #d4edda;
    color: #155724;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

