        new Recipe { Id = 2, Title = "Stuffed Mushrooms", Category = "appetizers", Ingredients = "Button mushrooms\nCream cheese\nGarlic\nParsley\nBreadcrumbs", Steps = "1. Remove mushroom stems\n2. Mix cream cheese, garlic, parsley\n3. Fill caps with mixture\n4. Top with breadcrumbs\n5. Bake at 375°F for 20 min", AverageRating = 4.5, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Spaghetti Carbonara", Category = "main-courses", Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan\nBlack pepper", Steps = "1. Cook spaghetti al dente\n2. Fry pancetta until crisp\n3. Whisk eggs with parmesan\n4. Toss hot pasta with pancetta\n5. Stir in egg mixture off heat", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 4, Title = "Grilled Salmon", Category = "main-courses", Ingredients = "Salmon fillets\nLemon\nDill\nOlive oil\nSalt and pepper", Steps = "1. Season salmon with salt, pepper, dill\n2. Drizzle with olive oil\n3. Grill skin-side down 4-5 min\n4. Flip and cook 3 min more\n5. Squeeze lemon over top", AverageRating = 4.6, RatingCount = 12 },
