        new Recipe { Id = 6, Title = "Tiramisu", Category = "desserts", Ingredients = "Ladyfingers\nMascarpone\nEspresso\nCocoa powder\nEggs\nSugar", Steps = "1. Whisk egg yolks with sugar\n2. Fold in mascarpone\n3. Dip ladyfingers in espresso\n4. Layer cookies and cream\n5. Dust with cocoa\n6. Refrigerate 4 hours", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Mango Smoothie", Category = "beverages", Ingredients = "Mango\nYogurt\nHoney\nIce\nMilk", Steps = "1. Peel and chop mango\n2. Add all ingredients to blender\n3. Blend until smooth\n4. Serve immediately", AverageRating = 4.3, RatingCount = 10 },
        new Recipe { Id = 8, Title = "Iced Matcha Latte", Category = "beverages", Ingredients = "Matcha powder\nHot water\nMilk\nIce\nHoney (optional)", Steps = "1. Sift matcha into a cup\n2. Add hot water and whisk\n3. Fill glass with ice\n4. Pour milk over ice\n5. Add matcha and stir", AverageRating = 4.1, RatingCount = 7 },
    };

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category == category).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }
}
