@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

@if (recipe is not null)
{
    <PageTitle>@recipe.Title - RecipeShare</PageTitle>

    <nav><a href="/recipes/@recipe.Category">← Back to Category</a></nav>

    <h1>@recipe.Title</h1>
    <p>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>

    <h2>Ingredients</h2>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@step.TrimStart("0123456789. ".ToCharArray())</li>
        }
    </ol>

    <h2>Rate this Recipe</h2>
    <StarRating RecipeId="recipe.Id" />
}
else
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/">← Back to Home</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= selectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              title="@star star(s)">
            @(star <= selectedRating ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="rating-feedback">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

