@page "/submit"
@using RecipeShare.Services
@using RecipeShare.Models
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (successMessage is not null)
{
    <div class="alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="form-group">
        <label for="title">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" />
        <ValidationMessage For="() => model.Title" />
    </div>

    <div class="form-group">
        <label for="category">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-control">
            <option value="">-- Select a Category --</option>
            <option value="appetizers">Appetizers</option>
            <option value="main-courses">Main Courses</option>
            <option value="desserts">Desserts</option>
            <option value="beverages">Beverages</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" />
    </div>

    <div class="form-group">
        <label for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5" />
        <ValidationMessage For="() => model.Ingredients" />
    </div>

    <div class="form-group">
        <label for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="5" />
        <ValidationMessage For="() => model.Steps" />
    </div>

    <button type="submit" class="btn-submit">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };

        RecipeService.AddRecipe(recipe);
        successMessage = $"'{model.Title}' was submitted successfully!";
        model = new();
    }
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.form-control {
    width: 100%;
    max-width: 500px;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.btn-submit {
    background: #0366d6;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-submit:hover {
    background: #0256b9;
}

.alert-success {
    background: #d4edda;
    color: #155724;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

